const D=globalThis.CAREER_DATA,C=globalThis.CareerCore;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));
const statusValues=['Not started','Preparing','Submission uncertain','Applied','Interviewing','Offer received','Closed / not pursuing'];
let storageOK=true;const blockedKeys=new Set(),failedKeys=new Set();let storageNotice='';
function storageWarning(message){storageNotice=message;if($('.footer'))$('.footer').textContent=message}
function unreadable(key){blockedKeys.add(key);storageWarning('Saved records could not be read. The original data is preserved; changes to those records cannot be saved.')}
function read(key,fallback){try{const raw=localStorage.getItem('ahmad-'+key);return raw===null?fallback:JSON.parse(raw)}catch{unreadable(key);return fallback}}
function persist(key,value){if(blockedKeys.has(key)){toast(storageNotice);return false}try{localStorage.setItem('ahmad-'+key,JSON.stringify(value));failedKeys.delete(key);if(!failedKeys.size&&!blockedKeys.size){storageOK=true;storageNotice='';$('.footer').textContent='Built around your experience. Every next step stays yours.'}return true}catch{storageOK=false;failedKeys.add(key);storageWarning('Storage unavailable. Unsaved changes last only for this session.');toast('Device storage unavailable. Changes will last only for this session.');return false}}
const record=x=>x!==null&&typeof x==='object'&&!Array.isArray(x);
function validWorkspace(w){return record(w)&&Array.isArray(w.saved)&&w.saved.every(x=>typeof x==='string')&&record(w.states)&&Object.values(w.states).every(x=>statusValues.includes(x))&&record(w.savedDetails)&&Object.entries(w.savedDetails).every(([id,j])=>C.normalizeJob(j)&&j.id===id)}
let saved=[],states={},savedDetails={};
function applyWorkspace(w){saved=[...w.saved];states={...w.states};savedDetails=Object.fromEntries(Object.entries(w.savedDetails).map(([id,j])=>[id,C.normalizeJob(j)]))}
const workspace=read('workspace',null);
if(workspace!==null){if(validWorkspace(workspace))applyWorkspace(workspace);else unreadable('workspace')}
else{const legacy={saved:read('saved',[]),states:read('states',{}),savedDetails:read('saved-details',{})};if(validWorkspace(legacy))applyWorkspace(legacy);else unreadable('workspace');if(['saved','states','saved-details'].some(k=>blockedKeys.has(k)))unreadable('workspace')}
const profileFields=['years','degree','skills','achievements','preferredCity','minimumMonthlySAR','unknownSalary'];
const profileValue=(p,k)=>String(p[k]??(k==='unknownSalary'?'show':''));
const validProfile=p=>record(p)&&!Object.entries(p).some(([k,v])=>k==='years'?v!==''&&(!Number.isFinite(Number(v))||Number(v)<0||Number(v)>60):k==='preferredCity'?!['','riyadh'].includes(v):k==='unknownSalary'?!['show','hide'].includes(v):k==='minimumMonthlySAR'?typeof v!=='string'||C.canonicalMinimumSAR(v)!==v:typeof v!=='string');
const defaultProfile={preferredCity:'riyadh'};
let profile=read('profile',defaultProfile);if(!validProfile(profile)){unreadable('profile');profile={}}
let profileDraft={...profile},profileBase={...profile};
const validChecklist=c=>record(c)&&Object.values(c).every(x=>typeof x==='boolean');
let checklist=read('checklist',{});if(!validChecklist(checklist)){unreadable('checklist');checklist={}}
let live=C.normalizeLive(read('live',null));if(live)live.jobs=live.jobs.filter(j=>j.company!=='Qiddiya'&&C.relevance(j.title)>0);
let workspaceBase=JSON.stringify(workspace);
function syncWorkspace(){
 if(blockedKeys.has('workspace'))return true;
 const latest=read('workspace',null);if(latest!==null&&!validWorkspace(latest)){unreadable('workspace');return true}
 if(failedKeys.has('workspace')){
  if(JSON.stringify(latest)!==workspaceBase){storageWarning('Another tab saved newer records. Export your unsaved notes, then reload before making more changes.');toast(storageNotice);return false}
  return true;
 }
 workspaceBase=JSON.stringify(latest);if(latest!==null)applyWorkspace(latest);return true;
}
function persistWorkspace(){const value={saved,states,savedDetails};if(!persist('workspace',value))return false;workspaceBase=JSON.stringify(value);return true}
function storedAction(key,change){return navigator.locks?.request?navigator.locks.request('ahmad-career-'+key,change).catch(()=>toast('This change could not be saved. Please try again.')):change()}
function workspaceAction(change){return storedAction('workspace',()=>{if(syncWorkspace())return change()})}
function saveProfile(next){const submittedDraft={...next};profileDraft={...next};return storedAction('profile',()=>{
 const amount=C.canonicalMinimumSAR(next.minimumMonthlySAR??'');
 if(amount===null){toast('Enter minimum monthly pay as whole SAR from 0 to 1,000,000, or leave it blank.');return}
 next={...next,minimumMonthlySAR:amount};if(!validProfile(next)){toast('Check the profile fields and choose a valid city and unknown-salary policy.');return}
 const latest=read('profile',defaultProfile);if(!validProfile(latest)){unreadable('profile');toast(storageNotice);return}
 const edited=Object.keys(next).filter(k=>profileValue(next,k)!==profileValue(profileBase,k));
 const conflicts=edited.filter(k=>profileValue(latest,k)!==profileValue(profileBase,k)&&profileValue(latest,k)!==profileValue(next,k));
 if(conflicts.length&&!confirm('Another tab changed these profile fields: '+conflicts.join(', ')+'. Replace those saved values with this form? Cancel keeps your draft without overwriting them.')){toast('Your draft is preserved. Another tab’s profile was not overwritten.');return}
 profile={...latest,...Object.fromEntries(edited.map(k=>[k,next[k]]))};
 if(persist('profile',profile)){const laterEdits=Object.fromEntries(profileFields.filter(k=>profileValue(profileDraft,k)!==profileValue(submittedDraft,k)).map(k=>[k,profileDraft[k]]));profileBase={...profile};profileDraft={...profile,...laterEdits};render();toast(Object.keys(laterEdits).length?'Profile saved. Your newer edits remain unsaved.':'Profile details saved on this device.')}
})}
function saveChecklist(id,checked){return storedAction('checklist',()=>{
 const latest=read('checklist',{});if(!validChecklist(latest)){unreadable('checklist');toast(storageNotice);return}
 if(Object.keys(checklistPending).length&&JSON.stringify(latest)!==checklistBase){storageWarning('Another tab saved newer checklist choices. Export your unsaved notes, then reload before making more changes.');toast(storageNotice);return}
 checklistBase=JSON.stringify(latest);
 checklist={...latest,...checklistPending,[id]:checked};checklistPending[id]=checked;
 if(persist('checklist',checklist)){checklistPending={};checklistBase=JSON.stringify(checklist)}
})}
let checklistPending={},checklistBase=JSON.stringify(checklist);
function unrefreshed(job,snapshot=live){return Boolean(snapshot?.sources.some(s=>s.name===job.company&&C.sourceIncomplete(s))&&C.parsedDate(job.lastCheckedAt)?.time<C.parsedDate(snapshot.checkedAt)?.time)}
function coverageMessage(snapshot){const incomplete=(snapshot?.sources||[]).filter(C.sourceIncomplete);let message=incomplete.length?incomplete.map(s=>s.name+': '+(s.error||(s.limited?'Bounded sample; some listings were not checked':'Some checks failed'))).join(' · ')+'. Results may be incomplete.':'';if(snapshot?.jobs.some(j=>unrefreshed(j,snapshot)))message+=' Previous results for incompletely checked employers are retained and marked Not refreshed.';if(snapshot?.invalidJobs)message+=(message?' ':'')+snapshot.invalidJobs+' malformed listings were excluded.';return message}
let view='shortlist',query='',filter='all',sort='rank',busy=false,liveError='',searchNotice='',coverageWarning=coverageMessage(live),failedSources=[],nativeTimer;
let companyFilter='',ageWindow=0,employmentFilter='',hideTracked=false,addedOnly=false,applicationFilter='all';
const views={shortlist:'Your shortlist',live:'Live search',saved:'Saved opportunities',applications:'Applications',profile:'Your profile',salary:'Salary & negotiation',plan:'Application plan'};
if(read('dark',false))document.body.classList.add('dark');
function syncTheme(){ $('[data-action="theme"]').setAttribute('aria-pressed',String(document.body.classList.contains('dark'))) }
syncTheme();
const date=s=>s&&!isNaN(Date.parse(s))?new Intl.DateTimeFormat('en',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Riyadh'}).format(new Date(s.length===10?s+'T12:00:00Z':s)):'Not stated';
const deadline=s=>date(s)+(s?.length>10?' · '+new Date(s).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Riyadh'})+' Riyadh':'');
const money=n=>new Intl.NumberFormat('en-SA',{maximumFractionDigits:0}).format(n);
const link=(url,label,cls='link')=>`<a class="${cls}" href="${C.safeURL(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`;
const glyph=c=>({'Qiddiya':'Q','Roche':'R','Alcon':'A','Johnson & Johnson':'J&J','Novartis':'N','GSK':'G','BD':'BD'}[c]||c.slice(0,2));
function toast(s){if($('#job-dialog').open){const notice=$('#dialog-notice');if(notice){notice.textContent=s;notice.hidden=false}return}$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function allJobs(){return C.mergeJobs(D.jobs,Object.values(savedDetails),live?.jobs||[])}
function retainKnownJobs(acceptedLive=live?.jobs||[]){let updated=false;for(const job of C.mergeJobs(D.jobs,Object.values(savedDetails),acceptedLive)){if(!(savedDetails[job.id]||saved.includes(job.id)||states[job.id]&&states[job.id]!=='Not started'||D.jobs.some(j=>j.id===job.id)&&acceptedLive.some(j=>j.id===job.id)))continue;if(JSON.stringify(savedDetails[job.id])!==JSON.stringify(job)){savedDetails[job.id]=job;updated=true}}if(updated)persistWorkspace()}
function jobById(id){return allJobs().find(j=>j.id===id)||(dialogJob?.id===id?dialogJob:undefined)}
const recordDrafts=Object.create(null),recordKey=id=>'application-record-v1:'+encodeURIComponent(id);
function readApplicationRecord(id){const key=recordKey(id),value=read(key,null);if(value!==null&&!C.validApplicationRecord(value,id)){unreadable(key);return null}return value}
function recordDirty(d){return d&&(d.appliedAt!==(d.base?.appliedAt||'')||d.receiptNote!==(d.base?.receiptNote||''))}
function editApplicationRecord(id){
 const prior=recordDrafts[id];if(recordDirty(prior))return prior;
 const base=readApplicationRecord(id);return recordDrafts[id]={job:jobById(id),base,appliedAt:base?.appliedAt||'',receiptNote:base?.receiptNote||''};
}
async function saveApplicationRecord(id){
 const d=recordDrafts[id];if(!d)return false;
 const value={schema:1,jobId:id,appliedAt:d.appliedAt,receiptNote:d.receiptNote,updatedAt:new Date().toISOString()};
 if(!C.validApplicationRecord(value,id)){toast('Use a real application date no later than today in Riyadh, or leave it blank. Notes allow 2,000 characters.');return false}
 if(!navigator.locks?.request){toast('Safe record saving is unavailable in this browser. Your draft is kept for this session; download your notes before closing.');return false}
 try{return await navigator.locks.request('ahmad-career-'+recordKey(id),async()=>{
  const latest=readApplicationRecord(id);if(blockedKeys.has(recordKey(id))){toast(storageNotice);return false}
  if(JSON.stringify(latest)!==JSON.stringify(d.base)){toast('Another tab changed this record. Your draft is preserved. Download it before choosing Reload saved record.');return false}
  const retained=await workspaceAction(()=>{const job=jobById(id)||d.job;if(blockedKeys.has('workspace')||!job)return false;savedDetails[id]=job;return persistWorkspace()});
  if(!retained){toast('The opportunity could not be saved. Your application record draft is preserved.');return false}
  if(!persist(recordKey(id),value))return false;
  // Keep edits made while waiting for the lock as an unsaved draft.
  recordDrafts[id].base=value;updateRecordEditor(id);updateDialogApplication();if(['plan','applications'].includes(view))render();toast('Application date and note saved on this device. Status is unchanged.');return true;
 })}catch{toast('This record could not be saved. Your draft is preserved.');return false}
}
// Private planning records are independent of application receipts and stages.
const actionDrafts=Object.create(null),actionKey=id=>'next-action-v1:'+encodeURIComponent(id);
function readNextAction(id){const key=actionKey(id);try{const raw=localStorage.getItem('ahmad-'+key);if(raw===null)return null;const value=JSON.parse(raw);if(C.validNextAction(value,id))return value}catch{}unreadable(key);return null}
function actionDirty(d){return Boolean(d&&(d.dueOn!==(d.base?.dueOn||'')||d.actionNote!==(d.base?.actionNote||'')||d.completed!==(d.base?.completed||false)))}
function editNextAction(id){const prior=actionDrafts[id];if(actionDirty(prior)||prior?.saving)return prior;const base=readNextAction(id);return actionDrafts[id]={job:jobById(id),base,dueOn:base?.dueOn||'',actionNote:base?.actionNote||'',completed:base?.completed||false}}
function meaningfulAction(id){const value=readNextAction(id);return Boolean(value?.actionNote.trim()||blockedKeys.has(actionKey(id)))}
function actionEditLabel(d){return (actionDirty(d)?'Unsaved next action. ':'')+(d.base?'Last saved: '+d.base.updatedAt:'No next action saved.')}
function updateActionEditor(id){const form=$('#next-action-form');if(form?.dataset.record!==id)return;$('#action-edited').textContent=actionEditLabel(actionDrafts[id])}
function captureActionInput(target){const form=target.closest?.('#next-action-form');if(form&&['dueOn','actionNote'].includes(target.name)){const d=actionDrafts[form.dataset.record];if(d){d[target.name]=target.value;updateActionEditor(form.dataset.record)}}}
async function saveNextAction(id,completed){
 const d=actionDrafts[id];if(!d||d.saving)return false;
 // Completion applies only to the saved record, never silently saves a draft.
 if(typeof completed==='boolean'&&(actionDirty(d)||!d.base?.actionNote.trim())){toast('Save or reload your next action before marking it done or reopening it.');return false}
 const value={schema:1,jobId:id,dueOn:d.dueOn,actionNote:d.actionNote,completed:typeof completed==='boolean'?completed:d.completed,updatedAt:new Date().toISOString()};
 if(!value.actionNote.trim()&&!value.dueOn)value.completed=false;
 if(!C.validNextAction(value,id)){toast('Enter a next action of at most 500 characters and an optional real date. A date needs an action note.');return false}
 if(!navigator.locks?.request){toast('Safe record saving is unavailable in this browser. Your draft is kept; export it before closing.');return false}
 d.saving=true;
 try{return await navigator.locks.request('ahmad-career-'+actionKey(id),async()=>{
  const latest=readNextAction(id);if(blockedKeys.has(actionKey(id))){toast(storageNotice);return false}
  if(JSON.stringify(latest)!==JSON.stringify(d.base)){toast('Another tab changed this next action. Your draft is preserved. Export it before choosing Reload saved next action.');return false}
  const retained=await workspaceAction(()=>{const job=jobById(id)||d.job;if(blockedKeys.has('workspace')||!job)return false;savedDetails[id]=job;return persistWorkspace()});
  if(!retained){toast('The opportunity could not be retained. Your next action draft is preserved.');return false}
  if(!persist(actionKey(id),value))return false;
  d.base=value;d.completed=value.completed;updateActionEditor(id);updateActionCompletion(id);if(['plan','applications'].includes(view))render();toast('Next action saved privately on this device. No notification or message is sent.');return true;
 })}catch{toast('The next action could not be saved. Your draft is preserved.');return false}finally{d.saving=false}
}
function actionEditor(j){const d=editNextAction(j.id);return `<form id="next-action-form" data-record="${esc(j.id)}"><h3>Your next action</h3><p class="notice">A private, self-entered task on this device. No notifications, background monitoring or messages. Planning does not mean you have applied. Leave both fields blank to clear. Avoid passwords or confidential details.</p><label class="field">Next action<textarea id="action-note" name="actionNote" aria-describedby="action-limit">${esc(d.actionNote)}</textarea><small id="action-limit">Up to 500 Unicode characters. Included in tracking exports, never preparation drafts.</small></label><label class="field">Optional due date (Riyadh)<input id="action-date" name="dueOn" type="date" value="${esc(d.dueOn)}"></label><p id="action-edited" class="notice">${esc(actionEditLabel(d))}</p><div class="dialog-buttons"><button class="secondary" type="submit">Save next action</button><button class="secondary" type="button" data-action="reload-action" data-record="${esc(j.id)}">Reload saved next action</button><button id="action-completion" class="secondary" type="button" data-action="complete-action" data-record="${esc(j.id)}" ${d.base?.actionNote.trim()?'':'disabled'}>${d.base?.completed?'Reopen saved action':'Mark saved action done'}</button></div></form>`}
function updateActionCompletion(id){const b=$('#action-completion');if(b?.dataset.record!==id)return;const r=actionDrafts[id]?.base;b.disabled=!r?.actionNote.trim();b.textContent=r?.completed?'Reopen saved action':'Mark saved action done'}
function actionText(id){const r=readNextAction(id),d=actionDrafts[id];return `\nPRIVATE NEXT ACTION (SELF-ENTERED)\nSaved action: ${r?.actionNote||'Not recorded'}\nSaved due date (Riyadh): ${r?.dueOn||'No date'}\nSaved completion: ${r?.completed?'Done':'Not done'}${r?'\nAction last saved: '+r.updatedAt:''}${blockedKeys.has(actionKey(id))?'\nNext action is unreadable; original bytes preserved.':''}${actionDirty(d)?'\nUNSAVED next action draft\nAction: '+(d.actionNote||'[blank]')+'\nDue date (Riyadh): '+(d.dueOn||'No date')+'\nCompletion: '+(d.completed?'Done':'Not done'):''}`}
function nextActionsSection(){
 const all=allJobs().map(job=>({job,value:readNextAction(job.id)})),entries=all.filter(x=>x.value?.actionNote.trim()),unreadableActions=all.filter(x=>blockedKeys.has(actionKey(x.job.id)));
 const groups=[['overdue','Overdue'],['today','Today'],['next7days','Next 7 days'],['upcoming','Upcoming'],['undated','No due date'],['completed','Completed']];
 return `<section class="card next-actions"><h2>Your next actions</h2><p>Private tasks, grouped by Riyadh calendar day. No notifications or messages. Completed tasks stay visible.</p>${unreadableActions.map(({job})=>`<p class="notice"><button class="link" data-job="${esc(job.id)}">${esc(job.title)} · ${esc(job.company)}</button>: saved next action is unreadable. Original bytes are preserved; it cannot be overwritten.</p>`).join('')}${groups.map(([key,label])=>{const rows=entries.filter(x=>C.nextActionBucket(x.value)===key).sort((a,b)=>a.value.dueOn.localeCompare(b.value.dueOn)||a.job.title.localeCompare(b.job.title));return rows.length?`<h3>${label} <span class="muted">(${rows.length})</span></h3>${rows.map(({job,value})=>`<div class="next-action-row"><button class="link" data-job="${esc(job.id)}">${esc(job.title)} · ${esc(job.company)}</button><p class="action-note">${esc(value.actionNote)}</p><p class="notice">${value.dueOn?'Due '+esc(value.dueOn)+' · Riyadh':'No due date'} · ${value.completed?'Completed':'Unfinished'}${states[job.id]==='Closed / not pursuing'?' · Closed / not pursuing'+(!value.completed?' — reminder still unfinished':''):''}${job.kind==='archived'?' · Archived role':''}</p></div>`).join('')}`:''}).join('')||'<p>No next actions yet. Open a role to add a private task.</p>'}</section>`;
}
function closeRoleDialog(){const d=dialogJob&&actionDrafts[dialogJob.id];if(d?.saving){toast('Please wait for the next action save to finish.');return false}if(actionDirty(d)&&!confirm('Close with an unsaved next action? Your draft stays in this session; export or save it before leaving the app.'))return false;$('#job-dialog').close();return true}
function meaningfulRecord(id){const value=readApplicationRecord(id);return Boolean(value&&(value.appliedAt||value.receiptNote.trim()))}
function retainedJobs(includeDrafts=false){const current=allJobs(),drafts=[...Object.values(recordDrafts).filter(recordDirty),...Object.values(actionDrafts).filter(actionDirty)],extras=includeDrafts?drafts.filter(d=>d.job&&!current.some(j=>j.id===d.job.id)).map(d=>d.job):[];return C.dedupe([...current,...extras]).filter(j=>saved.includes(j.id)||states[j.id]&&states[j.id]!=='Not started'||meaningfulRecord(j.id)||meaningfulAction(j.id)||includeDrafts&&(recordDirty(recordDrafts[j.id])||actionDirty(actionDrafts[j.id])))}
function recordEditor(j){const d=editApplicationRecord(j.id);return `<form id="application-record-form" data-record="${esc(j.id)}"><h3>Application date and receipt note</h3><p class="notice">Optional, self-entered tracking details. Leave the date blank if unknown. Notes stay on this device and appear in downloaded tracking notes, never in preparation drafts. Avoid passwords, codes or confidential employer data.</p><label class="field">Application date, if known<input id="application-date" name="appliedAt" type="date" max="${C.saudiDay(new Date())}" value="${esc(d.appliedAt)}"></label><label class="field">Receipt / record note<textarea id="application-receipt" name="receiptNote" aria-describedby="record-limit">${esc(d.receiptNote)}</textarea><small id="record-limit">Up to 2,000 characters. Plain text only; no attachments.</small></label><p id="record-edited" class="notice">${esc(recordEditLabel(d))}</p><div class="dialog-buttons"><button class="secondary" type="submit">Save application record</button><button class="secondary" type="button" data-action="reload-record" data-record="${esc(j.id)}">Reload saved record</button></div></form>`}
function recordEditLabel(d){return (recordDirty(d)?'Unsaved draft. ':'')+(d.base?'Record last edited: '+d.base.updatedAt+' (not the application time).':'Application date not recorded unless you enter it.');}
function updateRecordEditor(id){const form=$('#application-record-form');if(!form||form.dataset.record!==id)return;const d=recordDrafts[id];$('#record-edited').textContent=recordEditLabel(d)}
function captureRecordInput(target){const form=target.closest?.('#application-record-form');if(form&&['appliedAt','receiptNote'].includes(target.name)){const d=recordDrafts[form.dataset.record];if(d){d[target.name]=target.value;updateRecordEditor(form.dataset.record)}}}
function recordText(id){const r=readApplicationRecord(id),d=recordDrafts[id];return `\nApplication date (self-entered): ${r?.appliedAt||'Not recorded'}\nReceipt / record note (self-entered): ${r?.receiptNote||'Not recorded'}${r?'\nRecord last edited (not application time): '+r.updatedAt:''}${blockedKeys.has(recordKey(id))?'\nStored metadata is unreadable; original bytes preserved.':''}${recordDirty(d)?'\nUNSAVED application record draft\nApplication date: '+(d.appliedAt||'Not recorded')+'\nReceipt / record note: '+d.receiptNote:''}`}
function attentionSection(){const jobs=retainedJobs(),records=Object.fromEntries(jobs.map(j=>[j.id,readApplicationRecord(j.id)])),tasks=C.attentionFor(jobs,states,records);return `<section class="card" style="margin-bottom:24px"><h2>Needs attention</h2><p>Prompts from your saved records. Recheck employer information; these are not eligibility decisions or automatic applications.</p>${tasks.map(t=>{const j=jobs.find(j=>j.id===t.jobId),label=t.kind==='confirm-submission'?'Confirm the previous submission before retrying':t.kind==='requirements'?'Review the role requirements':t.kind==='applied-date'?'Application date not recorded — add it if known':t.past?'Past listed deadline — verify employer status':'Recheck listed deadline';return `<div class="source-row"><div><button class="link" data-job="${esc(j.id)}">${esc(label)} — ${esc(j.title)}, ${esc(j.company)}</button><p class="notice">${t.kind==='confirm-submission'?'An uncertain submission is not confirmed. Check your employer account and acknowledgement before retrying.':t.kind==='requirements'?esc((j.gaps||['Read the complete employer requirements and confirm your evidence.']).join(' · ')):t.kind==='deadline'?'Listed deadline: '+esc(deadline(j.closes)):'Optional record detail; an unknown date is allowed.'}<br>Research checked: ${esc(j.researchCheckedAt||'Not researched')} · Employer checked: ${esc(j.lastCheckedAt||'Not recorded')}. Past checks do not establish current availability.</p></div></div>`}).join('')||'<p>No attention prompts from your saved records.</p>'}</section>`}
function setMenu(open){$('#sidebar').classList.toggle('open',open);const button=$('[data-action=menu]');button?.setAttribute?.('aria-expanded',String(open));const shade=$('.nav-backdrop');if(shade)shade.hidden=!open;const narrow=globalThis.matchMedia?.('(max-width:760px)').matches;$('.main-shell').inert=Boolean(open&&narrow);if(open&&narrow)$('#sidebar [data-action=close-menu]')?.focus?.();else if(!open)button?.focus?.()}
function go(next){if(!views[next])return;view=next;query='';filter='all';sort='rank';setMenu(false);render();$('#main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'})}
function intro(title,subtitle,eyebrow='YOUR CAREER, CONSIDERED'){return `<div class="eyebrow">${esc(eyebrow)}</div><div class="intro"><div><h1>${esc(title)}</h1><p>${subtitle}</p></div></div>`}
// Only repaint local date groups. This does not fetch, notify or touch dialog fields.
let dayRolloverTimer=null;
function scheduleDayRollover(){
 clearTimeout(dayRolloverTimer);dayRolloverTimer=null;
 if(document.visibilityState==='hidden'||!['plan','applications'].includes(view))return;
 const now=new Date(),next=Date.parse(C.saudiDay(now)+'T00:00:00+03:00')+86400000;
 dayRolloverTimer=setTimeout(()=>{dayRolloverTimer=null;if(document.visibilityState!=='hidden'&&['plan','applications'].includes(view))render()},Math.max(1,next-now.getTime()));
}
function resumeDayGroups(){if(document.visibilityState!=='hidden'&&['plan','applications'].includes(view))render();else scheduleDayRollover()}
function render(){
 scheduleDayRollover();
 const active=document.activeElement,insideMain=$('#main').contains?.(active),focusName=insideMain?active?.name:null,focusNodeID=insideMain?active?.id:null,selection=insideMain&&typeof active?.selectionStart==='number'?[active.selectionStart,active.selectionEnd]:null,focusKey=active?.dataset?.save?'save':active?.dataset?.job?'job':null,focusID=focusKey?active.dataset[focusKey]:null;
 $('#view-name').textContent=views[view];$('#saved-count').textContent=saved.length;$('#top-count').textContent=D.jobs.length||(live?.jobs||[]).filter(j=>C.criteriaFor(j,profile).included).length;
 $$('.nav-item').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});
 const pages={shortlist:shortlistPage,live:livePage,saved:savedPage,applications:applicationsPage,profile:profilePage,salary:salaryPage,plan:planPage};
 $('#main').innerHTML=pages[view](); if(['shortlist','live','saved'].includes(view))renderList();
 updateSearchButtons();if(insideMain&&(focusNodeID||focusName)){const next=focusNodeID?document.getElementById(focusNodeID):$$('[name]').find(x=>x.name===focusName);next?.focus?.({preventScroll:true});if(selection)next?.setSelectionRange?.(...selection)}else if(insideMain&&focusID){const next=$$('[data-'+focusKey+']').find(x=>x.dataset[focusKey]===focusID);(next||$('#main')).focus({preventScroll:true})}
}
function updateSearchButtons(){$$('.new-search').forEach(b=>{b.disabled=busy;b.innerHTML=(busy?'<span class="spinner"></span>':'<span aria-hidden="true">✧</span>')+(busy?' Searching employers…':' Find new openings')})}
function addedInComparison(id){return Boolean(live?.searchComparison?.addedIds.includes(id))}
function comparisonDate(value){return date(value)+' '+new Date(C.parsedDate(value).time).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit',timeZone:'Asia/Riyadh'})+' Riyadh'}
function searchChanges(){
 if(!live)return '';const c=live.searchComparison;
 if(!c)return '<section class="card"><h2>Search changes unavailable</h2><p>This cached result has no comparison history. Run another search to compare result lists.</p></section>';
 const timing=`Search: ${esc(comparisonDate(c.checkedAt))}`;
 if(c.previousCheckedAt===null)return `<section class="card"><h2>Search baseline established</h2><p>${timing}. This first result list is the baseline; no additions are claimed.</p></section>`;
 return `<section class="card"><h2>${c.addedIds.length} listing${c.addedIds.length===1?'':'s'} added to results</h2><p>${timing}<br>Compared with: ${esc(comparisonDate(c.previousCheckedAt))}</p><p>Added means absent from the previous result list, including returning listings. It does not mean newly created, first discovered or a verified qualification match. Republishing an existing listing does not count as an addition. Missing listings are not proof of closure. Counts cover the full result list before your filters.</p>${live.sources.some(C.sourceIncomplete)?'<p class="notice">Coverage was incomplete. Dated previous results may be retained.</p>':''}</section>`;
}
function toolbar(){
 const options=(rows,current)=>rows.map(([value,label])=>`<option value="${esc(value)}" ${String(value)===String(current)?'selected':''}>${esc(label)}</option>`).join('');
 const discovery=['shortlist','live'].includes(view),base=D.jobs.length?allJobs():live?.jobs||[];
 const companies=[...new Set(base.map(j=>j.company))].sort(),types=[...new Set(base.map(j=>j.employmentType).filter(x=>x&&x!=='Not stated'))].sort();
 return `<div class="toolbar"><label class="searchbox"><span aria-hidden="true">⌕</span><input id="search" type="search" aria-label="Search these opportunities" placeholder="Search roles, companies or skills" value="${esc(query)}"></label><select id="filter" aria-label="Filter opportunities">${options([['all','All opportunities'],['software','Software & AI'],['early','Early-career evidence'],['riyadh','Riyadh'],['open','Not past deadline']],filter)}</select><select id="sort" aria-label="Sort opportunities">${options([['rank',view==='live'||!D.jobs.length?'Title relevance':'Research priority'],['deadline','Closing soon'],['recent','Latest employer date']],sort)}</select>${discovery?`<select id="company-filter" aria-label="Employer">${options([['','All employers'],...companies.map(x=>[x,x]),...(companyFilter&&!companies.includes(companyFilter)?[[companyFilter,companyFilter+' (not in current results)']]:[])],companyFilter)}</select><select id="age-window" aria-label="Employer publication date">${options([[0,'Any publication date'],[7,'Employer date: last 7 days'],[30,'Employer date: last 30 days'],[90,'Employer date: last 90 days']],ageWindow)}</select><select id="employment-filter" aria-label="Employment type">${options([['','All employment types'],...types.map(x=>[x,x]),...(employmentFilter&&!types.includes(employmentFilter)?[[employmentFilter,employmentFilter+' (not in current results)']]:[])],employmentFilter)}</select><label class="filter-toggle"><input id="added-only" type="checkbox" ${addedOnly?'checked':''}> Added in this comparison</label><label class="filter-toggle"><input id="hide-tracked" type="checkbox" ${hideTracked?'checked':''}> Hide roles with application records</label><button class="text-button" data-action="reset-discovery">Reset filters</button>`:''}</div>${discovery?'<p class="filter-explanation">Dates are the employer’s publication or last-republication dates, not when a job was first created. A date filter excludes unknown dates. Tracking filters use this device’s records only.</p>':''}`;
}
function publicationTag(j){return `<span class="tag">${C.publicationLabel(j)} ${date(j.posted)}</span>`}
function evidenceSection(j){
 const notes=j.requirementNotes||[],level=j.experienceLevel;
 return `<section class="evidence-panel"><h3>Employer evidence to review</h3>${level?`<p><strong>Employer experience label:</strong> ${esc(level)}. A label does not establish your eligibility.</p>`:''}<p><strong>Employment type:</strong> ${esc(j.employmentType||'Not stated')} · <strong>Arrangement:</strong> ${esc(j.mode||'Not stated')}</p>${notes.length?`<ul>${notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul><p class="notice">Selected employer excerpts, not a complete requirements assessment. Required versus preferred wording and equivalent-experience alternatives still need your review.</p>`:'<p class="notice">Detailed requirements were not captured from this public feed. Read the official description before deciding to apply.</p>'}<p class="notice">Personal projects do not count automatically as professional employment. No degree, student status, work authorization or paid status is assumed.</p>${link(j.sourceUrl||j.url,'Read the full employer description')}</section>`;
}
function applicationAdvisory(j){const records=allJobs().filter(x=>meaningfulRecord(x.id)).map(x=>x.id),messages=C.applicationWarnings(j,allJobs(),states,records);return messages.length?`<div class="callout"><div><strong>Check your existing applications</strong>${messages.map(x=>`<p>${esc(x)}</p>`).join('')}</div></div>`:''}
function applicationLinkLabel(j){return C.isExpired(j.closes)?'Check employer status':states[j.id]&&states[j.id]!=='Not started'||meaningfulRecord(j.id)?'View employer / existing application':'Open official application'}
function updateDialogApplication(){if(!dialogJob||!$('#job-dialog').open)return;const j=jobById(dialogJob.id)||dialogJob;const advisory=$('#application-advisory'),open=$('#application-open-link');if(advisory)advisory.innerHTML=applicationAdvisory(j);if(open)open.textContent=applicationLinkLabel(j)}
function applicationJobs(){return retainedJobs().filter(j=>states[j.id]&&states[j.id]!=='Not started'||meaningfulRecord(j.id)||meaningfulAction(j.id))}
function applicationsPage(){
 const jobs=applicationJobs(),search=query.trim().toLowerCase(),visible=jobs.filter(j=>(applicationFilter==='all'||(states[j.id]||'Not started')===applicationFilter)&&(!search||[j.title,j.company].join(' ').toLowerCase().includes(search)));
 const groups=statusValues.filter(status=>visible.some(j=>(states[j.id]||'Not started')===status));
 return `${intro('Keep every application clear.','Separate preparation, uncertain submissions and confirmed outcomes. Updating a stage only changes your local record.','APPLICATIONS')}${nextActionsSection()}<div class="metric-grid"><div><strong>${jobs.length}</strong><span>Tracked roles</span></div><div><strong>${jobs.filter(j=>states[j.id]==='Submission uncertain').length}</strong><span>Need confirmation</span></div><div><strong>${jobs.filter(j=>['Applied','Interviewing','Offer received'].includes(states[j.id])).length}</strong><span>Marked submitted or later</span></div></div><div class="callout"><div><strong>A local stage is not a submission receipt.</strong><p>Use Submission uncertain when a form may have been sent but confirmation is missing. Verify the employer account or acknowledgement before retrying. No messages or applications are sent here.</p></div></div><div class="toolbar"><label class="searchbox"><span aria-hidden="true">⌕</span><input id="application-search" type="search" placeholder="Search tracked roles" aria-label="Search applications" value="${esc(query)}"></label><select id="application-filter" aria-label="Application stage"><option value="all">All stages</option>${statusValues.map(status=>`<option value="${esc(status)}" ${status===applicationFilter?'selected':''}>${status==='Not started'?'Record only':esc(status)}</option>`).join('')}</select><button class="secondary" data-action="export">Review tracking notes</button></div>${visible.length?groups.map(status=>{const rows=visible.filter(j=>(states[j.id]||'Not started')===status);return `<section class="application-group"><div class="section-line"><h2>${status==='Not started'?'Record only':esc(status)}</h2><span>${rows.length} role${rows.length===1?'':'s'}</span></div><div class="job-list">${rows.map(row).join('')}</div></section>`}).join(''):'<div class="empty"><h2>No application records match.</h2><p>Open a role and set its stage or save a receipt note. Existing records are never deleted by these filters.</p><button class="secondary" data-view="live">Review discovered roles</button></div>'}`;
}
function discoveryOverview(){
 const jobs=(live?.jobs||[]).filter(j=>C.criteriaFor(j,profile).included),recent=jobs.filter(j=>C.discoveryMatches(j,{days:7})),age=live?C.ageInSaudiDays(live.checkedAt):null;
 return `<section class="discovery-overview"><div class="metric-grid"><div><strong>${jobs.length}</strong><span>Current cached leads</span></div><div><strong>${recent.length}</strong><span>Employer date in last 7 days</span></div><div><strong>${applicationJobs().length}</strong><span>Application records</span></div></div><p class="notice">${live?`Last successful search: ${date(live.checkedAt)}${age!==null&&age>=7?' · Cached evidence is at least a week old; refresh before applying.':''}`:'Run a search to create your first source-verified result list.'} Listings need eligibility and paid-status review.</p><button class="text-button" data-view="applications">Open application board</button></section>`;
}

function criteriaSummary(){const floor=Number(profile.minimumMonthlySAR)>0;return `<div class="criteria-summary"><div><strong>Your discovery criteria</strong><p>${profile.preferredCity==='riyadh'?'Riyadh required; multiple-city assignments need confirmation':'Any Saudi city'} · ${floor?'Minimum monthly pay SAR '+money(Number(profile.minimumMonthlySAR))+'; pay basis to confirm':'No minimum pay set'}${floor?' · '+(profile.unknownSalary==='hide'?'Hide unverified pay':'Show unverified pay'):''}</p><small>Private to this browser or app on this device. Used only for discovery; saved roles and application history remain available.</small></div><button class="text-button" data-view="profile">Edit profile</button></div>`}
function criteriaTags(j){const c=C.criteriaFor(j,profile);return `${c.city==='conditional'?'<span class="tag warn">Confirm Riyadh assignment</span>':c.city==='outside'?'<span class="tag warn">Outside preferred city</span>':''}${c.salary==='unverified'?'<span class="tag warn">Salary unverified — confirm your minimum</span>':''}`}
function shortlistPage(){return `${intro('Your next chapter.','Discover paid software, Python and AI opportunities. Add your own background and preferences in Profile.','YOUR SALEH CAREER FINDER')}${discoveryOverview()}${searchChanges()}<div class="summary-line"><span><strong>Riyadh</strong> first</span><span><strong>Software & AI</strong> focus</span><span>Your profile stays on this device</span></div><div class="callout"><span class="symbol" aria-hidden="true">✧</span><div><strong>Your projects are your evidence.</strong><p>Target junior and early-career opportunities. Keep personal projects separate from paid employment, and check degree requirements before applying. No vacancies have been prefilled or invented for this new workspace.</p></div></div>${criteriaSummary()}<section class="card"><h2>Start with your strongest work</h2><p>Python and AI tooling · Swift/SwiftUI apps · TypeScript and backend systems. ${link(D.profile.url,'Review your GitHub portfolio')} before choosing examples for an application.</p><p class="notice">Live search checks public technology-company boards at Mozn, Lucidya, Foodics, Salla, Lean Technologies, Tamara and Unifonic. It includes currently listed software and AI titles, with early-career wording prioritized. This is selected-board coverage, not the entire Riyadh market. A zero result does not mean there are no suitable jobs.</p><button class="primary" data-action="refresh">Find new openings</button></section>${toolbar()}<div class="section-line"><h2>${D.jobs.length?'Researched opportunities':'Discovered opportunities to review'}</h2><span id="result-count" role="status" aria-live="polite"></span></div><div class="job-list" id="job-list"></div><details class="disclosure"><summary>How matches are screened</summary><p>Live search uses software/AI title and Saudi-location evidence. Junior, graduate, intern and associate titles receive higher priority; titles explicitly requiring senior, lead, manager or director level are excluded. This is title screening, not a qualification assessment. Confirm paid status, full requirements, salary and current availability with the employer.</p><p>Your saved roles and application history stay on this device. Existing records are preserved when upgrading this app.</p></details>`}
function row(j,index){const expired=C.isExpired(j.closes),isSaved=saved.includes(j.id);return `<article class="job-row"><span class="rank">${String(view==='shortlist'?(j.rank||index+1):index+1).padStart(2,'0')}</span><span class="company-logo" aria-hidden="true">${esc(j.initials||glyph(j.company))}</span><div><button class="job-title" data-job="${esc(j.id)}">${esc(j.title)}</button><div class="job-meta">${esc(j.company)} · ${esc(j.location)}${j.mode&&j.mode!=='Not stated'?' · '+esc(j.mode):''}</div><p class="job-summary">${esc(j.summary)}</p><div class="tags"><span class="tag ${expired?'warn':'good'}">${expired?'Past listed deadline':j.kind==='archived'?'Archived research':j.kind==='live'?'Employer listing':'Research '+date(j.researchCheckedAt||D.checkedAt)}</span><span class="tag ${/stretch|fallback/.test(j.fit)?'warn':''}">${esc(j.fit)}</span>${addedInComparison(j.id)?'<span class="tag good">Added in this comparison</span>':''}${criteriaTags(j)}${publicationTag(j)}${j.employmentType&&j.employmentType!=='Not stated'?`<span class="tag">${esc(j.employmentType)}</span>`:''}${j.experienceLevel?`<span class="tag">Level: ${esc(j.experienceLevel)}</span>`:''}<span class="tag">${j.kind==='archived'?'Archived salary evidence':j.rank?'Salary undisclosed in research':'Salary not checked'}</span>${unrefreshed(j)?'<span class="tag warn">Not refreshed — previous result</span>':''}${j.lastCheckedAt?`<span class="tag">Employer checked ${date(j.lastCheckedAt)}</span>`:''}${j.closes?`<span class="tag">${expired?'Listed deadline':'Closes'} ${deadline(j.closes)}</span>`:''}${states[j.id]?`<span class="tag">${esc(states[j.id])}</span>`:''}</div></div><div class="job-actions"><button class="secondary" data-job="${esc(j.id)}">View role</button><button class="save-button ${isSaved?'saved':''}" data-save="${esc(j.id)}" aria-label="${isSaved?'Unsave':'Save'} ${esc(j.title)}" aria-pressed="${isSaved}">${isSaved?'♥':'♡'}</button></div></article>`}
function renderList(){let list=view==='shortlist'?(D.jobs.length?D.jobs:(live?.jobs||[])).map(j=>jobById(j.id)):view==='live'?(live?.jobs||[]).map(j=>jobById(j.id)):allJobs().filter(j=>saved.includes(j.id));
 const discovery=view==='shortlist'||view==='live';if(discovery)list=list.filter(j=>(!addedOnly||addedInComparison(j.id))&&C.criteriaFor(j,profile).included&&C.discoveryMatches(j,{company:companyFilter,days:ageWindow,employmentType:employmentFilter})&&(!hideTracked||(!states[j.id]||states[j.id]==='Not started')&&!meaningfulRecord(j.id)));
 const salaryHidden=discovery&&Number(profile.minimumMonthlySAR)>0&&profile.unknownSalary==='hide';
 const term=query.toLowerCase().trim();list=list.filter(j=>!term||[j.title,j.company,j.location,j.summary,...(j.gaps||[])].join(' ').toLowerCase().includes(term));
 list=list.filter(j=>filter==='all'||filter==='software'&&C.relevance(j.title)>0||filter==='early'&&(j.relevance??C.relevance(j.title))>=95||filter==='riyadh'&&C.riyadhCity(j.location)!=='outside'||filter==='open'&&!C.isExpired(j.closes));
 if(sort==='deadline')list.sort((a,b)=>(C.dateSortTime(a.closes,true)??Infinity)-(C.dateSortTime(b.closes,true)??Infinity));else if(sort==='recent')list.sort((a,b)=>(C.dateSortTime(b.posted)??-Infinity)-(C.dateSortTime(a.posted)??-Infinity));else list.sort((a,b)=>view==='live'?(b.relevance||0)-(a.relevance||0):(a.rank||100)-(b.rank||100)||(b.relevance||0)-(a.relevance||0));
 if($('#result-count'))$('#result-count').textContent=list.length+' '+(list.length===1?'opportunity':'opportunities')+(discovery&&Number(profile.minimumMonthlySAR)>0&&list.length?' · salary unverified':'');
 if($('#job-list')&&busy&&view==='live'&&!list.length){$('#job-list').innerHTML='<div class="empty"><span class="spinner"></span><h2>Searching employer boards…</h2><p>Checking published roles, Saudi locations and application status.</p></div>';return}if($('#job-list'))$('#job-list').innerHTML=list.length?list.map(row).join(''):`<div class="empty"><h2>${salaryHidden?'Monthly pay is not verified':discovery&&addedOnly?'No added listings match these filters':query||filter!=='all'?'No matching opportunities':view==='saved'?'Make a shortlist of your own.':'No matching openings yet.'}</h2><p>${salaryHidden?'Current listings have no verified comparable monthly pay, and your criteria hide unverified salaries. This does not mean there are no vacancies. Edit your profile to review these leads while confirming your minimum.':discovery&&addedOnly?'Only listings absent from the previous result list appear here. A baseline or older cache has no additions. Turn off this filter to see all results.':query||filter!=='all'?'Try a broader search or choose all opportunities.':view==='saved'?'Tap the heart on any role to keep it here. Saved roles and progress stay on this device.':'Search the employer boards. A successful search can return zero suitable roles; errors are shown separately.'}</p>${salaryHidden?'<button class="secondary" data-view="profile">Edit profile</button>':view==='live'?'<button class="primary" data-action="refresh">Search employers</button>':''}</div>`;
}
function livePage(){return `${intro('Find the next opportunity.','Search selected employer boards for Saudi software and AI roles. Coverage is limited, and every lead needs review.','LIVE EMPLOYER SEARCH')}<button class="primary" data-action="refresh" ${busy?'disabled':''}>${busy?'<span class="spinner"></span> Searching…':'Find new openings'}</button><p class="notice">Mozn · Lucidya · Foodics · Salla · Lean Technologies · Tamara · Unifonic. No sign-in or CV is sent to search. These are listings to review, not verified matches or proof of newly created vacancies.</p>${searchNotice?`<p class="notice" role="status">${esc(searchNotice)}</p>`:''}${liveError?`<div class="callout"><div><strong>Search could not finish</strong><p>${esc(liveError)} Your researched shortlist and previous results are preserved.</p>${failedSources.map(s=>`<p>${esc(s.name)}: ${esc(s.error||'Unavailable')}</p>`).join('')}</div></div>`:''}${coverageWarning?`<div class="callout"><div><strong>Search coverage is incomplete</strong><p>${esc(coverageWarning)}</p></div></div>`:''}${live?`<div class="section-line"><h2>${liveError?'Previous successful search':'Latest search'}</h2><span>${date(live.checkedAt)} · ${new Date(live.checkedAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Riyadh'})} Riyadh</span></div><details class="disclosure"><summary>${live.sources.filter(s=>s.ok).length} of ${live.sources.length} employers responded · view search coverage</summary>${live.sources.map(s=>`<div class="source-row"><strong>${esc(s.name)}</strong><span class="${s.ok?'':'error'}">${s.ok?`${esc(s.count??0)} matching · ${esc(s.scanned??'—')} scanned${s.limited?' · bounded sample':''}${s.error?' · '+esc(s.error):s.detailErrors?' · '+esc(s.detailErrors)+' details unavailable':''}`:esc(s.error||'Unavailable')}</span></div>`).join('')}<p>Searches a bounded sample of selected boards. Title filtering can miss suitable roles; multiple-location and missing-detail jobs may be excluded. Source failures never mean an employer has no jobs. No coverage of the entire Saudi market is implied.</p></details>`:''}${searchChanges()}${criteriaSummary()}${toolbar()}<div class="section-line"><h2>Listings to review</h2><span id="result-count" role="status" aria-live="polite"></span></div><div class="job-list" id="job-list"></div>`}
function savedPage(){return `${intro('The ones worth pursuing.','Your selected opportunities, with application progress in one place.','SAVED OPPORTUNITIES')}<p class="notice">Saved on this device only. Website, iPhone and Mac progress do not sync.</p>${toolbar()}<div class="section-line"><h2>Your shortlist</h2><span id="result-count" role="status" aria-live="polite"></span></div><div class="job-list" id="job-list"></div>`}
function profilePage(){return `${intro('Start with what is true.','A clear picture of your experience makes every application stronger.','YOUR PROFILE')}<div class="grid-two"><section class="card"><div class="card-label">YOUR STARTING PROFILE</div><h2>${esc(D.profile.name)}</h2><p>${esc(D.profile.role)}<br>${esc(D.profile.organization)}<br>${esc(D.profile.location)}</p><ul class="fact-list">${D.profile.facts.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>${link(D.profile.url,'Open your profile link')}</p><p class="notice">Add your own background and requirements. Skills are self-reported; this is not independent credential verification. Your private CV, contact details and application logs are not bundled here. Confirm role-specific evidence before applying.</p></section><section class="card"><div class="card-label">STILL TO CONFIRM</div><h2>The details that change fit</h2><ul class="fact-list">${D.profile.unknowns.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>Do not count university attendance or personal projects as employment. Describe what you built, your contribution and what you can demonstrate without claiming a completed degree or client work.</p></section></div><section class="card" style="margin-top:20px"><h2>Add your own details</h2><p>These stay in this browser or app on this device. Your professional details support application notes and experience warnings; discovery criteria only refine the lists you see. Nothing here is sent to employers or used to claim verified qualifications.</p><form id="profile-form"><div class="inline-fields"><label class="field">Years of formal relevant employment<input name="years" type="number" min="0" max="60" step="0.5" placeholder="Not yet provided" value="${esc(profileDraft.years??'')}"></label><label class="field">Degree and certifications<input name="degree" maxlength="300" placeholder="Your exact qualification" value="${esc(profileDraft.degree||'')}"></label></div><label class="field">Tools and responsibilities<textarea name="skills" maxlength="3000" placeholder="Languages, tools, personal projects and your contribution…">${esc(profileDraft.skills||'')}</textarea></label><label class="field">Achievements you can substantiate<textarea name="achievements" maxlength="5000" placeholder="What changed, by how much, over what period, and your contribution. Avoid confidential employer data.">${esc(profileDraft.achievements||'')}</textarea></label><fieldset class="criteria-fields"><legend>Private discovery criteria</legend><p>These preferences refine your shortlist and live leads on this device. They are excluded from application notes and search requests.</p><label class="field">Preferred work city<select name="preferredCity"><option value="" ${profileDraft.preferredCity!=='riyadh'?'selected':''}>Any Saudi city</option><option value="riyadh" ${profileDraft.preferredCity==='riyadh'?'selected':''}>Riyadh — confirm any multiple-city assignment</option></select></label><label class="field">Minimum monthly pay, SAR<input name="minimumMonthlySAR" type="text" inputmode="decimal" maxlength="32" placeholder="No minimum set" value="${esc(profileDraft.minimumMonthlySAR??'')}" aria-describedby="minimum-pay-help"><small id="minimum-pay-help">Whole SAR from 0 to 1,000,000; blank or zero means no minimum. Confirm basic salary versus fixed package with the employer. Current listings have no verified comparable pay.</small></label><label class="field">Listings with unverified pay<select id="unknown-salary" name="unknownSalary" ${Number(C.canonicalMinimumSAR(profileDraft.minimumMonthlySAR??''))>0?'':'disabled'}><option value="show" ${profileDraft.unknownSalary!=='hide'?'selected':''}>Show and confirm my minimum</option><option value="hide" ${profileDraft.unknownSalary==='hide'?'selected':''}>Hide from discovery</option></select><small>This choice applies only when a minimum is set. Unknown pay is never treated as meeting it.</small></label></fieldset><button class="primary" type="submit">Save on this device</button></form></section>`}
function salaryPage(){return `${intro('Compare the whole offer.','Use the actual role, working hours and written terms to assess an opportunity.','SALARY & NEGOTIATION')}<div class="callout"><span class="symbol">▥</span><div><strong>No salary target has been invented.</strong><p>Your minimum is optional. There is no verified software/AI salary benchmark in this workspace, and unknown pay never counts as meeting your minimum. Ask whether an internship or training role is paid before investing time.</p></div></div><section class="card" style="margin-top:24px"><h2>Compare a package</h2><p>Enter monthly amounts in SAR. Keep discretionary bonus separate from guaranteed pay.</p><form id="package-form"><div class="inline-fields"><label class="field">Monthly basic salary<input name="base" type="number" min="0" max="1000000" step="1" value="0"></label><label class="field">Monthly fixed housing & transport<input name="allowances" type="number" min="0" max="1000000" step="1" value="0"></label></div><label class="field">Target annual bonus (not guaranteed)<input name="bonus" type="number" min="0" max="10000000" step="1" value="0"></label><div class="highlight-note" id="package-result" role="status" aria-live="polite" aria-atomic="true"><p>Fixed monthly: <strong>SAR 0</strong><br>Guaranteed annual: <strong>SAR 0</strong><br>Including target bonus: <strong>SAR 0</strong></p></div></form></section><section class="card" style="margin-top:20px"><h2>Questions to ask</h2><ol class="steps"><li><strong>Confirm the work and pay.</strong><span>What will I build, is this paid employment, and what is the approved salary range?</span></li><li><strong>Check the requirements.</strong><span>Does your experience and education meet this role’s requirements?</span></li><li><strong>Compare the full package.</strong><span>Get basic salary, allowances, bonus, hours, location, probation and benefits in writing.</span></li><li><strong>Use honest evidence.</strong><span>Show a project, explain your contribution and discuss what you learned. Do not invent employment or competing offers.</span></li></ol></section>`}
const planItems=[['profile','Confirm your factual profile','Use your exact qualifications. Separate personal projects, study and employment.'],['evidence','Prepare three project stories','Explain the problem, your code and decisions, a demo or test, and what you learned.'],['cv','Tailor your software and AI CV','Choose the relevant Python, Swift or TypeScript examples. Do not claim a completed degree or professional experience you do not have.'],['priority','Prioritize paid junior software and AI roles','Check location, paid status, required degree and experience before tailoring.'],['deadline','Check current requirements and deadlines','Verify the employer listing and check existing application records to avoid duplicates.'],['review','Review each application yourself','Verify every field and uploaded file. This app never submits applications automatically.']];
function planPage(){return `${intro('A thoughtful application beats ten generic ones.','Focus first on evidence, then on a small number of well-matched roles.','YOUR APPLICATION PLAN')}${nextActionsSection()}${attentionSection()}<div class="grid-two"><section class="card"><h2>Your preparation checklist</h2><p>Progress stays on this device.</p>${planItems.map(([id,t,s])=>`<label class="check-row"><input type="checkbox" id="check-${id}" data-check="${id}" ${checklist[id]?'checked':''}><span>${esc(t)}<small>${esc(s)}</small></span></label>`).join('')}</section><section class="card"><div class="card-label">POSITIONING TO TEST</div><h2>Make your projects concrete.</h2><p>Lead with a working project, the problem it solves, your contribution and how you tested it. Be explicit that the work is a personal project, not paid employment or client work.</p><div class="highlight-note"><p>“In my personal project [name], I built [feature] using [tools]. I tested it with [method] and learned [specific lesson]. Here is the code or demo.”</p></div><p>Replace every bracket with facts you can substantiate. Do not turn a prototype into a claim of production or customer impact.</p><button class="secondary" data-action="export" style="margin-top:18px">Download my application notes</button></section></div><div class="section-line"><h2>Application records</h2><span>Manually maintained</span></div>${retainedJobs().filter(j=>states[j.id]&&states[j.id]!=='Not started'||meaningfulRecord(j.id)).map((j,i)=>row(j,i)).join('')||'<div class="empty"><h2>No applications marked yet.</h2><p>Open a role and update its application status after you complete a step.</p><button class="secondary" data-view="shortlist">Review your opportunities</button></div>'}`}
let dialogReturn=null,dialogJob=null;
function rememberDialogOpener(){if(!$('#job-dialog').open){const e=document.activeElement;dialogReturn={element:e,job:e?.dataset?.job,save:e?.dataset?.save}}}
const dialogNotice=()=>`<p id="dialog-notice" class="dialog-notice" role="status" aria-live="polite" ${storageNotice?'':'hidden'}>${esc(storageNotice)}</p>`;
function openJob(id){rememberDialogOpener();const j=jobById(id);if(!j)return;dialogJob=j;const exp=C.isExpired(j.closes);const years=profile.years;const gap=years!==undefined&&years!==''&&j.minYears&&Number(years)<j.minYears;
 $('#job-dialog').innerHTML=`<div class="dialog-top"><span class="muted" style="font-size:.8rem">${j.rank?'PRIORITY '+String(j.rank).padStart(2,'0'):j.kind==='archived'?'ARCHIVED ROLE':'NEW EMPLOYER LEAD'} · ${esc(j.company)}</span><button class="icon-button" data-action="close" aria-label="Close role details">×</button></div><div class="dialog-body"><span class="tag ${exp?'warn':'good'}">${exp?'Past listed deadline':j.kind==='archived'?'Archived research':j.kind==='live'?'Live search result':'Research '+date(j.researchCheckedAt||D.checkedAt)}</span><h2 id="dialog-title">${esc(j.title)}</h2><p class="muted">${esc(j.company)} · ${esc(j.location)}${j.mode&&j.mode!=='Not stated'?' · '+esc(j.mode):''}<br>${esc(j.subtitle||'')}</p><div class="tags">${addedInComparison(j.id)?'<span class="tag good">Added in this comparison</span>':''}${criteriaTags(j)}${publicationTag(j)}<span class="tag">${j.closes?'Closes '+deadline(j.closes):'No closing date published'}</span><span class="tag">${j.kind==='archived'?'Archived salary evidence':j.rank?'Salary undisclosed in research':'Salary not checked'}</span></div>${gap?`<div class="callout"><div><strong>Your entered experience is below this requirement.</strong><p>You entered ${esc(years)} relevant years. This listing asks for ${j.minYears}+; review eligibility before applying.</p></div></div>`:''}${unrefreshed(j)?'<p class="notice">Not refreshed in the latest attempt. This previous result is retained because its latest employer check was incomplete or bounded.</p>':''}${j.lastCheckedAt?`<p class="notice">Employer listing last checked ${date(j.lastCheckedAt)}. A past search does not guarantee the vacancy is still open.</p>`:''}${j.kind==='archived'?`<p class="notice">This role is preserved from your earlier records and is outside the current shortlist. Original research date: ${j.researchCheckedAt?date(j.researchCheckedAt):'unavailable'}. Recheck all requirements and availability.</p>`:''}<div id="application-advisory" aria-live="polite">${applicationAdvisory(j)}</div>${evidenceSection(j)}<h3>Why it is on your list</h3><p>${esc(j.summary)}</p><p class="notice">${esc(j.fit)}. This assessment is provisional until your full career history, qualifications and actual responsibilities are confirmed.</p><h3>What to establish first</h3><ul>${(j.gaps||['Read the complete employer requirements and confirm experience, degree, location, work eligibility and seniority.','This lead was found by title and location. It has not received the full research review of the shortlist.']).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Your application, step by step</h3><ol class="steps">${(j.steps||[['Read the official description','Confirm the position is still open and compare every mandatory requirement with your experience.'],['Tailor your evidence','Select two actual achievements that demonstrate the responsibilities. Do not invent credentials or outcomes.'],['Apply personally','Use the employer’s application route, review the form and attachments, then submit only when you are ready.'],['Keep the receipt','Save the acknowledgement and update the status below.']]).map(([t,s])=>`<li><strong>${esc(t)}</strong><span>${esc(s)}</span></li>`).join('')}</ol><h3>Application status</h3><select class="status-select" data-status="${esc(j.id)}" aria-label="Application status">${statusValues.map(x=>`<option ${states[j.id]===x?'selected':''}>${x}</option>`).join('')}</select><p class="notice">This is your own tracking record. Changing it does not submit an application or contact anyone.</p>${recordEditor(j)}${actionEditor(j)}<div class="dialog-buttons">${link(j.applyUrl||j.url,applicationLinkLabel(j),'primary').replace('<a ','<a id="application-open-link" ')}<button class="secondary" data-save="${esc(j.id)}">${saved.includes(j.id)?'Remove from saved':'Save opportunity'}</button><button class="secondary" data-draft="${esc(j.id)}">Prepare application note</button></div><p class="notice">${link(j.sourceUrl||j.url,'View source and full requirements')} · Recheck salary, deadline and eligibility directly with the employer. Application forms may change.</p></div>`;
 $('#job-dialog').insertAdjacentHTML?.('beforeend',dialogNotice());if(!$('#job-dialog').open)$('#job-dialog').showModal();
}
function toggleSaved(id){return workspaceAction(()=>{const j=jobById(id);if(!j)return;if(saved.includes(id))saved=saved.filter(x=>x!==id);else saved.push(id);savedDetails[id]=j;const savedOK=persistWorkspace();render();if($('#job-dialog').open){openJob(id);$('#job-dialog [data-save]')?.focus?.()}if(savedOK)toast(saved.includes(id)?'Saved on this device.':'Removed from saved opportunities.')})}
function noteValue(key,current,valid){
 if(blockedKeys.has(key)||failedKeys.has(key)||key==='checklist'&&Object.keys(checklistPending).length)return current;
 const latest=read(key,{});if(blockedKeys.has(key))return current;
 if(!valid(latest)){unreadable(key);return current}return latest;
}
function draft(j){const p=noteValue('profile',profile,validProfile);return `Application preparation note — ${j.title}, ${j.company}\n\nI am interested in this opportunity and would like to explore how my personal software and AI projects relate to the role.\n\nBefore using this draft, add only verified experience and results that meet these requirements:\n${(j.gaps||['Review the employer requirements.']).map(x=>'• '+x).join('\n')}\n\nMy evidence (self-entered, review for accuracy):\n${p.achievements||'[Add two accurate achievements, their measurement period and your own contribution.]'}\n\nOfficial vacancy: ${j.url}\n\nThis is an unsent preparation draft. Review and rewrite it before using it in an application.`}
function exportNotes(){if(!failedKeys.has('workspace'))syncWorkspace();const p=noteValue('profile',profile,validProfile),checks=noteValue('checklist',checklist,validChecklist);const text=`SALEH CAREER FINDER — APPLICATION NOTES\nResearch snapshot: ${D.checkedAt}\nExported: ${new Date().toISOString()}\nSaudi Arabia only. Saved locally; this app does not submit applications.\n\nPROFILE (SELF-ENTERED)\nFormal relevant employment years: ${p.years??'Not provided'}\nQualifications: ${p.degree||'Not provided'}\nTools and scope: ${p.skills||'Not provided'}\nAchievements: ${p.achievements||'Not provided'}\n\n${retainedJobs(true).map(j=>`${j.title} — ${j.company}\n${j.url}\n${j.location}\n${j.kind==='archived'?'Archived research — outside the current shortlist.\n':''}Research checked: ${j.researchCheckedAt||'Not researched'}\nEmployer checked: ${j.lastCheckedAt||'Not recorded'}\nListed deadline: ${j.closes||'Not stated'}\nStatus: ${states[j.id]||'Not started'}${recordText(j.id)}${actionText(j.id)}\n${j.summary}\n${(j.gaps||[]).join('\n')}`).join('\n\n')}\n\nPREPARATION\n${planItems.map(([id,t])=>(checks[id]?'[x] ':'[ ] ')+t).join('\n')}`;if(window.webkit?.messageHandlers?.careerSearch){showNotes(text,true);return}const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.download='Saleh-Career-Finder-application-notes.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function showNotes(text,tracking=false){rememberDialogOpener();const dialog=$('#job-dialog');dialog.innerHTML=`<div class="dialog-top"><strong id="dialog-title">Your application notes</strong><button class="icon-button" data-action="close" aria-label="Close notes">×</button></div><div class="dialog-body"><p class="notice">${tracking?'Tracking export includes your self-entered profile, receipt notes, private next actions and any unsaved record drafts. Review before sharing.':'Unsent preparation draft. Review all claims before using.'}</p><label class="field">Notes<textarea id="note-text" readonly style="min-height:340px">${esc(text)}</textarea></label><button class="primary" data-action="copy-notes">Copy notes</button></div>`;dialog.insertAdjacentHTML?.('beforeend',dialogNotice());if(!dialog.open)dialog.showModal();$('#note-text')?.focus?.()}
function receiveLive(payload){return storedAction('live',()=>{
 const latest=C.normalizeLive(read('live',null));if(latest&&(!live||C.parsedDate(latest.checkedAt).time>C.parsedDate(live.checkedAt).time))live=latest;
 acceptLive(payload);
})}
function acceptLive(payload){
 clearTimeout(nativeTimer);busy=false;failedSources=[];searchNotice='';coverageWarning=coverageMessage(live);
 const incoming=C.normalizeLive(payload);
 if(!incoming)liveError=typeof payload?.error==='string'?payload.error:'The search returned an invalid response.';
 else if(!incoming.sources.length||incoming.sources.every(s=>!s.ok)){
  failedSources=incoming.sources;liveError='All selected employer sources were unavailable. Try again later.';
 }else if(live&&C.parsedDate(incoming.checkedAt).time<=C.parsedDate(live.checkedAt).time){
  if(C.parsedDate(incoming.checkedAt).time<C.parsedDate(live.checkedAt).time)liveError='An older search response was ignored.';
  else{liveError='';searchNotice='No newer search snapshot is available. Using the last successful results and their original comparison.'}
 }else{
  incoming.jobs=incoming.jobs.filter(j=>j.company!=='Qiddiya'&&C.relevance(j.title)>0&&!C.isExpired(j.closes)&&!C.isFuture(j.posted));
  const ids=new Set(incoming.jobs.map(j=>j.id)),incomplete=new Set(incoming.sources.filter(C.sourceIncomplete).map(s=>s.name));
  incoming.jobs.push(...(live?.jobs||[]).filter(j=>!ids.has(j.id)&&incomplete.has(j.company)&&!incoming.sources.some(s=>s.name===j.company&&s.excludedIds?.includes(j.id))&&!C.isExpired(j.closes)&&!C.isFuture(j.posted)&&C.relevance(j.title)>0));
  if(incoming.jobs.length>1000)liveError='The combined results exceed the 1,000-listing cache limit. The previous successful search and comparison are preserved.';
  else{
   incoming.searchComparison=C.compareSearches(live,incoming);live=incoming;persist('live',live);
   const acceptedJobs=live.jobs;workspaceAction(()=>retainKnownJobs(acceptedJobs));liveError='';coverageWarning=coverageMessage(incoming);
  }
 }
 if(['live','plan','shortlist','saved','applications'].includes(view))render();else updateSearchButtons();
 toast(liveError?'Search could not finish; previous results were retained.':searchNotice?searchNotice:coverageWarning?'Some employer checks were incomplete.':'Employer search finished. Review the coverage notes.');
}
window.receiveNativeJobs=receiveLive;
async function refresh(){if(busy)return;busy=true;liveError='';searchNotice='';coverageWarning='';view='live';query='';filter='all';sort='rank';setMenu(false);render();$('#main').focus({preventScroll:true});
 if(window.webkit?.messageHandlers?.careerSearch){nativeTimer=setTimeout(()=>receiveLive({error:'The native search timed out. Please try again.'}),65000);window.webkit.messageHandlers.careerSearch.postMessage({action:'refresh'});return}
 try{const response=await fetch('/api/live',{headers:{Accept:'application/json'},signal:AbortSignal.timeout(65000)});if(!response.ok)throw Error('Search service returned '+response.status);receiveLive(await response.json())}catch(e){receiveLive({error:location.protocol==='file:'?'Open this website through its local server, or use the iPhone/Mac app to search live sources.':e.message||'Search is unavailable.'})}
}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a[data-view]');if(!b)return;if(b.dataset.view){go(b.dataset.view);return}if(b.dataset.job){openJob(b.dataset.job);return}if(b.dataset.save){toggleSaved(b.dataset.save);return}if(b.dataset.draft){const j=jobById(b.dataset.draft);if(j)showNotes(draft(j));return}
 switch(b.dataset.action){case'refresh':refresh();break;case'reset-discovery':companyFilter='';ageWindow=0;employmentFilter='';hideTracked=false;addedOnly=false;query='';filter='all';sort='rank';render();break;case'menu':setMenu(!$('#sidebar').classList.contains('open'));break;case'close-menu':setMenu(false);break;case'theme':document.body.classList.toggle('dark');syncTheme();persist('dark',document.body.classList.contains('dark'));break;case'close':closeRoleDialog();break;case'reload-action':{const id=b.dataset.record,d=actionDrafts[id];if(d?.saving){toast('Please wait for the save to finish.');break}if(!actionDirty(d)||confirm('Discard this unsaved next action and reload the saved version?')){delete actionDrafts[id];openJob(id)}break}case'complete-action':{const id=b.dataset.record;return saveNextAction(id,!actionDrafts[id]?.base?.completed)}case'copy-notes':{const area=$('#note-text');try{if(navigator.clipboard)await navigator.clipboard.writeText(area.value);else{area.select();if(!document.execCommand('copy'))throw Error('copy')}toast('Notes copied. Review before using.')}catch{area.focus();area.select();toast('Select and copy the notes manually.')}break}case'reload-record':{const id=b.dataset.record;if(!recordDirty(recordDrafts[id])||confirm('Discard this unsaved application record draft and load the saved version?')){delete recordDrafts[id];openJob(id)}break}case'export':exportNotes();break}});
function captureProfileInput(target){if(target.closest?.('#profile-form')&&profileFields.includes(target.name)){profileDraft[target.name]=target.value;if(target.name==='minimumMonthlySAR')$('#unknown-salary').disabled=!(Number(C.canonicalMinimumSAR(target.value))>0)}}
document.addEventListener('input',e=>{captureProfileInput(e.target);captureRecordInput(e.target);captureActionInput(e.target);if(e.target.id==='search'){query=e.target.value;renderList()}if(e.target.id==='application-search'){query=e.target.value;render()}if(e.target.closest('#package-form')){const f=new FormData($('#package-form'));const safe=(n,max)=>{const raw=String(f.get(n)??'').trim(),v=Number(raw);return /^\d+$/.test(raw)&&Number.isSafeInteger(v)&&v>=0&&v<=max?v:null};const base=safe('base',1e6),allowances=safe('allowances',1e6),bonus=safe('bonus',1e7);if([base,allowances,bonus].some(v=>v===null)){$('#package-result').textContent='Enter whole SAR amounts: basic and allowances from 0 to 1,000,000, bonus from 0 to 10,000,000.';return}const monthly=base+allowances,annual=monthly*12;$('#package-result').innerHTML=`<p>Fixed monthly: <strong>SAR ${money(monthly)}</strong><br>Guaranteed annual: <strong>SAR ${money(annual)}</strong><br>Including target bonus: <strong>SAR ${money(annual+bonus)}</strong></p>`}});
document.addEventListener('change',e=>{captureProfileInput(e.target);captureRecordInput(e.target);captureActionInput(e.target);if(e.target.id==='company-filter'){companyFilter=e.target.value;renderList()}if(e.target.id==='age-window'){ageWindow=[0,7,30,90].includes(Number(e.target.value))?Number(e.target.value):0;renderList()}if(e.target.id==='employment-filter'){employmentFilter=e.target.value;renderList()}if(e.target.id==='added-only'){addedOnly=e.target.checked;renderList()}if(e.target.id==='hide-tracked'){hideTracked=e.target.checked;renderList()}if(e.target.id==='application-filter'){applicationFilter=e.target.value;render()}if(e.target.id==='filter'){filter=e.target.value;renderList()}if(e.target.id==='sort'){sort=e.target.value;renderList()}if(e.target.dataset.check)return saveChecklist(e.target.dataset.check,e.target.checked);if(e.target.dataset.status){return workspaceAction(()=>{const id=e.target.dataset.status;if(!statusValues.includes(e.target.value))return;const j=jobById(id);if(!j)return;states[id]=e.target.value;savedDetails[id]=j;const stateOK=persistWorkspace();render();updateDialogApplication();if(stateOK)toast('Application status saved on this device.')})}});
document.addEventListener('submit',e=>{if(e.target.id==='next-action-form'){e.preventDefault();return saveNextAction(e.target.dataset.record)}if(e.target.id==='application-record-form'){e.preventDefault();return saveApplicationRecord(e.target.dataset.record)}if(e.target.id==='package-form'){e.preventDefault();return}if(e.target.id!=='profile-form')return;e.preventDefault();const f=new FormData(e.target);const next={years:f.get('years')===''?'':Math.max(0,Math.min(60,Number(f.get('years')))),degree:String(f.get('degree')).slice(0,300),skills:String(f.get('skills')).slice(0,3000),achievements:String(f.get('achievements')).slice(0,5000),preferredCity:String(f.get('preferredCity')||''),minimumMonthlySAR:String(f.get('minimumMonthlySAR')||''),unknownSalary:String(f.get('unknownSalary')||profileDraft.unknownSalary||'show')};return saveProfile(next)});
$('#job-dialog').addEventListener('cancel',e=>{e.preventDefault();closeRoleDialog()});
window.addEventListener?.('beforeunload',e=>{if(Object.values(actionDrafts).some(d=>actionDirty(d)||d.saving)){e.preventDefault();e.returnValue=''}});
$('#job-dialog').addEventListener('close',()=>{const opener=dialogReturn;const target=opener?.element?.isConnected?opener.element:opener?.job?$$('[data-job]').find(e=>e.dataset.job===opener.job):opener?.save?$$('[data-save]').find(e=>e.dataset.save===opener.save):null;(target?.getClientRects?.().length?target:$('#main')).focus({preventScroll:true});dialogReturn=null;dialogJob=null});
$('#job-dialog').addEventListener('click',e=>{if(e.target===$('#job-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeRoleDialog()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#sidebar').classList.contains('open'))setMenu(false)});
window.addEventListener?.('resize',()=>{if(!globalThis.matchMedia?.('(max-width:760px)').matches)setMenu(false)});
window.addEventListener?.('storage',e=>{if(e.key?.startsWith('ahmad-next-action-v1:')){if(dialogJob&&$('#job-dialog').open){const id=dialogJob.id,d=actionDrafts[id];if(d&&!actionDirty(d)&&!d.saving){editNextAction(id);const form=$('#next-action-form');if(form?.dataset.record===id){$('#action-date').value=actionDrafts[id].dueOn;$('#action-note').value=actionDrafts[id].actionNote;updateActionEditor(id);updateActionCompletion(id)}}}if(['plan','applications'].includes(view)&&!$('#job-dialog').open)render()}if(e.key?.startsWith('ahmad-application-record-v1:')){if(dialogJob&&$('#job-dialog').open){const id=dialogJob.id,d=recordDrafts[id];if(d&&!recordDirty(d)){editApplicationRecord(id);const form=$('#application-record-form');if(form?.dataset.record===id){$('#application-date').value=recordDrafts[id].appliedAt;$('#application-receipt').value=recordDrafts[id].receiptNote;updateRecordEditor(id)}}}updateDialogApplication();if(['plan','applications'].includes(view)&&!$('#job-dialog').open)render()}if(e.key==='ahmad-workspace'&&!failedKeys.has('workspace')){syncWorkspace();if($('#job-dialog').open&&dialogJob){const button=$('#job-dialog [data-save]'),status=$('#job-dialog [data-status]');if(button)button.textContent=saved.includes(dialogJob.id)?'Remove from saved':'Save opportunity';if(status)status.value=states[dialogJob.id]||'Not started';updateDialogApplication()}if(['saved','plan','shortlist','live','applications'].includes(view)&&!$('#job-dialog').open)render()}});
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'search_researched_opportunities',title:'Search researched opportunities',description:'Read the existing researched shortlist by text. Does not fetch, apply or send data.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:200}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input.query!=='string'||input.query.length>200||Object.keys(input).some(k=>k!=='query'))throw Error('Provide only a query of at most 200 characters.');const q=input.query.toLowerCase();return D.jobs.filter(j=>[j.title,j.company,j.summary].join(' ').toLowerCase().includes(q)).map(({title,company,location,rank,url,fit,closes,posted,researchCheckedAt})=>({title,company,location,rank,url,fit,closes,posted,researchCheckedAt:researchCheckedAt||D.checkedAt,evidenceNotice:'Dated research; confirm worksite, requirements and current availability with the employer.'}))}})}catch{}}
document.addEventListener('visibilitychange',resumeDayGroups);
window.addEventListener?.('pageshow',resumeDayGroups);
workspaceAction(retainKnownJobs);
render();
